using System;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Shell;using System.Windows.Automation;
public static class MacFrame {
 static Brush Color(string hex){return (Brush)new BrushConverter().ConvertFrom(hex);}
 static LinearGradientBrush AppleAccent(){return new LinearGradientBrush(new GradientStopCollection{new GradientStop(System.Windows.Media.Color.FromRgb(91,125,255),0),new GradientStop(System.Windows.Media.Color.FromRgb(155,101,240),.5),new GradientStop(System.Windows.Media.Color.FromRgb(235,119,179),1)},new Point(0,0),new Point(1,1));}
 public static Button[] Attach(Window window,FrameworkElement content){window.WindowStyle=WindowStyle.None;window.ResizeMode=ResizeMode.CanResize;WindowChrome.SetWindowChrome(window,new WindowChrome{CaptionHeight=42,ResizeBorderThickness=new Thickness(5),GlassFrameThickness=new Thickness(0),CornerRadius=new CornerRadius(16),UseAeroCaptionButtons=false});var shell=new DockPanel{Background=window.Background,LastChildFill=true};var caption=new Grid{Height=42,Background=new LinearGradientBrush(System.Windows.Media.Color.FromRgb(249,249,255),System.Windows.Media.Color.FromRgb(251,240,250),0)};DockPanel.SetDock(caption,Dock.Top);shell.Children.Add(caption);var title=new TextBlock{Text=window.Title,FontSize=12,Foreground=Color("#786887"),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};caption.Children.Add(title);var lights=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(18,0,0,0)};caption.Children.Add(lights);var close=TrafficLight("#FF5F57","×","关闭",()=>SystemCommands.CloseWindow(window));var minimize=TrafficLight("#FEBC2E","−","最小化",()=>SystemCommands.MinimizeWindow(window));var maximize=TrafficLight("#28C840","+","最大化 / 还原",()=>{if(window.WindowState==WindowState.Maximized)SystemCommands.RestoreWindow(window);else SystemCommands.MaximizeWindow(window);});lights.Children.Add(close);lights.Children.Add(minimize);lights.Children.Add(maximize);var controls=new[]{close,minimize,maximize};var rule=new Border{Height=2,Background=AppleAccent(),Opacity=.65};DockPanel.SetDock(rule,Dock.Top);shell.Children.Add(rule);shell.Children.Add(content);window.Content=new Border{Child=shell,Background=window.Background,CornerRadius=new CornerRadius(16),BorderBrush=Color("#DCD8E8"),BorderThickness=new Thickness(1)};
 window.SourceInitialized+=(s,e)=>{var source=HwndSource.FromHwnd(new WindowInteropHelper(window).Handle);if(source!=null)source.AddHook(MacMonitorBounds);};return controls;
 }
 static Button TrafficLight(string color,string glyph,string name,Action action){var b=new Button{Width=14,Height=14,Margin=new Thickness(0,0,8,0),Background=Color(color),BorderThickness=new Thickness(0),ToolTip=name,Focusable=false,Content=glyph,FontSize=11,Foreground=Color("#503D3D"),Padding=new Thickness(0)};b.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border Background='{TemplateBinding Background}' CornerRadius='7'><ContentPresenter x:Name='symbol' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' HorizontalAlignment='Center' VerticalAlignment='Center' Opacity='0'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='symbol' Property='Opacity' Value='1'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");AutomationProperties.SetName(b,name);WindowChrome.SetIsHitTestVisibleInChrome(b,true);b.Click+=(s,e)=>action();return b;}
 [StructLayout(LayoutKind.Sequential)]struct NativePoint{public int X,Y;}
 [StructLayout(LayoutKind.Sequential)]struct MinMax{public NativePoint Reserved,MaxSize,MaxPosition,MinTrack,MaxTrack;}
 [StructLayout(LayoutKind.Sequential)]struct NativeRect{public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential)]struct MonitorData{public int Size;public NativeRect Monitor,Work;public int Flags;}
 [DllImport("user32.dll")]static extern IntPtr MonitorFromWindow(IntPtr window,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Auto)]static extern bool GetMonitorInfo(IntPtr monitor,ref MonitorData data);
 static IntPtr MacMonitorBounds(IntPtr hwnd,int message,IntPtr wParam,IntPtr lParam,ref bool handled){if(message!=0x24)return IntPtr.Zero;var monitor=MonitorFromWindow(hwnd,2);var info=new MonitorData{Size=Marshal.SizeOf(typeof(MonitorData))};if(monitor!=IntPtr.Zero&&GetMonitorInfo(monitor,ref info)){var bounds=(MinMax)Marshal.PtrToStructure(lParam,typeof(MinMax));var source=HwndSource.FromHwnd(hwnd);var owner=source==null?null:source.RootVisual as Window;if(owner!=null){var scale=source.CompositionTarget.TransformToDevice;bounds.MinTrack.X=Math.Max(bounds.MinTrack.X,(int)Math.Ceiling(owner.MinWidth*scale.M11));bounds.MinTrack.Y=Math.Max(bounds.MinTrack.Y,(int)Math.Ceiling(owner.MinHeight*scale.M22));}bounds.MaxPosition.X=info.Work.Left-info.Monitor.Left;bounds.MaxPosition.Y=info.Work.Top-info.Monitor.Top;bounds.MaxSize.X=info.Work.Right-info.Work.Left;bounds.MaxSize.Y=info.Work.Bottom-info.Work.Top;Marshal.StructureToPtr(bounds,lParam,true);handled=true;}return IntPtr.Zero;}
}
